/**
 * Technical indicators (pure functions, no I/O).
 *
 * Definition of done mapping (ta_ai_completion_conditions.txt section B, acceptance criteria):
 *  (a) B-7(1) indicators match golden values: tests/domain/technical/indicators.test.ts
 *      (textbook values + independent pandas vectors in tests/fixtures/technical/, generated by
 *      scripts/generate_technical_fixtures.py, relative tolerance 1e-9).
 *  (b) B-7(2)/B-6 key price zones + pivots: synthetic known-swing unit tests and determinism /
 *      append-stability property tests: keyZones.test.ts, indicators.test.ts.
 *  (c) B-7(4) gaps / weekends do not break computation: resample.test.ts (gap + FX-week cases),
 *      plus no-look-ahead, length-alignment and warm-up-null property tests.
 *  Not covered here (later phases): API exposure, storage, iOS rendering, real-data owner review.
 *
 * Conventions (documented because libraries differ):
 *  - Every function returns an array of the same length as its input; indices without enough
 *    history are null. The value at index i only uses inputs at indices <= i.
 *  - EMA / Wilder smoothing are seeded with the SMA of the first `period` values (TA-Lib and
 *    StockCharts convention), not with the first raw value.
 *  - Inputs are assumed finite and chronologically ordered.
 */
import { assertPeriod, type Bar, type Series } from './types.js';

function nulls(n: number): Series {
  return new Array<number | null>(n).fill(null);
}

export function sma(values: readonly number[], period: number): Series {
  assertPeriod(period);
  const out = nulls(values.length);
  let sum = 0;
  for (let i = 0; i < values.length; i++) {
    sum += values[i]!;
    if (i >= period) sum -= values[i - period]!;
    if (i >= period - 1) out[i] = sum / period;
  }
  return out;
}

/** Linearly weighted MA: weights 1..period, newest bar has the largest weight. */
export function wma(values: readonly number[], period: number): Series {
  assertPeriod(period);
  const out = nulls(values.length);
  const denom = (period * (period + 1)) / 2;
  for (let i = period - 1; i < values.length; i++) {
    let s = 0;
    for (let k = 0; k < period; k++) s += values[i - period + 1 + k]! * (k + 1);
    out[i] = s / denom;
  }
  return out;
}

/**
 * Recursive smoothing seeded with the SMA of the first `period` non-null values.
 * `alpha` = 2/(period+1) for EMA, 1/period for Wilder. Leading nulls in `values` are skipped
 * (used for the MACD signal line). Output is null until the seed is available.
 */
function seededSmoothing(values: Series, period: number, alpha: number): Series {
  const out = nulls(values.length);
  const first = values.findIndex((x) => x !== null);
  if (first < 0) return out;
  const seedIdx = first + period - 1;
  if (seedIdx >= values.length) return out;
  let seed = 0;
  for (let i = first; i <= seedIdx; i++) seed += values[i]!;
  let prev = seed / period;
  out[seedIdx] = prev;
  for (let i = seedIdx + 1; i < values.length; i++) {
    prev = prev + alpha * (values[i]! - prev);
    out[i] = prev;
  }
  return out;
}

export function ema(values: readonly number[], period: number): Series {
  assertPeriod(period);
  return seededSmoothing(values as Series, period, 2 / (period + 1));
}

/** Wilder's smoothing (alpha = 1/period), SMA-seeded. */
export function wilder(values: readonly number[], period: number): Series {
  assertPeriod(period);
  return seededSmoothing(values as Series, period, 1 / period);
}

/**
 * Wilder RSI. Changes start at index 1, so the first value is at index `period`
 * (seed = simple mean of the first `period` gains / losses). If avg loss is 0, RSI = 100
 * (or 50 when both averages are 0, i.e. a perfectly flat window).
 */
export function rsi(closes: readonly number[], period = 14): Series {
  assertPeriod(period);
  const out = nulls(closes.length);
  if (closes.length <= period) return out;
  let avgGain = 0;
  let avgLoss = 0;
  for (let i = 1; i <= period; i++) {
    const d = closes[i]! - closes[i - 1]!;
    if (d > 0) avgGain += d;
    else avgLoss -= d;
  }
  avgGain /= period;
  avgLoss /= period;
  const toRsi = (g: number, l: number): number => (l === 0 ? (g === 0 ? 50 : 100) : 100 - 100 / (1 + g / l));
  out[period] = toRsi(avgGain, avgLoss);
  for (let i = period + 1; i < closes.length; i++) {
    const d = closes[i]! - closes[i - 1]!;
    avgGain = (avgGain * (period - 1) + (d > 0 ? d : 0)) / period;
    avgLoss = (avgLoss * (period - 1) + (d < 0 ? -d : 0)) / period;
    out[i] = toRsi(avgGain, avgLoss);
  }
  return out;
}

export interface MacdResult {
  macd: Series;
  signal: Series;
  histogram: Series;
}

/** MACD = EMA(fast) - EMA(slow); signal = EMA(signalPeriod) of MACD (SMA-seeded); hist = macd - signal. */
export function macd(closes: readonly number[], fast = 12, slow = 26, signalPeriod = 9): MacdResult {
  if (fast >= slow) throw new RangeError('fast must be < slow');
  assertPeriod(signalPeriod, 'signalPeriod');
  const f = ema(closes, fast);
  const s = ema(closes, slow);
  const line: Series = closes.map((_, i) => (f[i] != null && s[i] != null ? f[i] - s[i] : null));
  const signal = seededSmoothing(line, signalPeriod, 2 / (signalPeriod + 1));
  const histogram: Series = line.map((m, i) => (m != null && signal[i] != null ? m - signal[i] : null));
  return { macd: line, signal, histogram };
}

export interface BollingerResult {
  middle: Series;
  upper: Series;
  lower: Series;
}

/** Bollinger Bands: SMA +/- mult * population standard deviation (ddof = 0, as in StockCharts/TA-Lib). */
export function bollinger(closes: readonly number[], period = 20, mult = 2): BollingerResult {
  assertPeriod(period);
  const middle = sma(closes, period);
  const upper = nulls(closes.length);
  const lower = nulls(closes.length);
  for (let i = period - 1; i < closes.length; i++) {
    const m = middle[i]!;
    let sq = 0;
    for (let k = i - period + 1; k <= i; k++) sq += (closes[k]! - m) ** 2;
    const sd = Math.sqrt(sq / period);
    upper[i] = m + mult * sd;
    lower[i] = m - mult * sd;
  }
  return { middle, upper, lower };
}

/** True range. Index 0 has no previous close, so it is null (TA-Lib convention). */
export function trueRange(bars: readonly Bar[]): Series {
  return bars.map((b, i) => {
    if (i === 0) return null;
    const pc = bars[i - 1]!.c;
    return Math.max(b.h - b.l, Math.abs(b.h - pc), Math.abs(b.l - pc));
  });
}

/** Wilder ATR: first value (index `period`) = mean of TR[1..period], then Wilder smoothing. */
export function atr(bars: readonly Bar[], period = 14): Series {
  assertPeriod(period);
  const tr = trueRange(bars);
  const out = nulls(bars.length);
  if (bars.length <= period) return out;
  let prev = 0;
  for (let i = 1; i <= period; i++) prev += tr[i]!;
  prev /= period;
  out[period] = prev;
  for (let i = period + 1; i < bars.length; i++) {
    prev = (prev * (period - 1) + tr[i]!) / period;
    out[i] = prev;
  }
  return out;
}

export interface StochasticResult {
  k: Series;
  d: Series;
}

function smaOfSeries(s: Series, n: number): Series {
  assertPeriod(n);
  const first = s.findIndex((x) => x !== null);
  const res = nulls(s.length);
  if (first < 0) return res;
  sma(s.slice(first) as number[], n).forEach((x, j) => {
    res[first + j] = x;
  });
  return res;
}

/**
 * Stochastic oscillator (default 14,3,3 = "slow"): raw %K = 100*(C-LL)/(HH-LL) over `kPeriod`,
 * %K = SMA(raw, kSmooth), %D = SMA(%K, dPeriod). Use kSmooth = 1 for the "fast" variant.
 * A flat window (HH == LL) gives raw %K = 0 (TA-Lib convention).
 */
export function stochastic(bars: readonly Bar[], kPeriod = 14, kSmooth = 3, dPeriod = 3): StochasticResult {
  assertPeriod(kPeriod, 'kPeriod');
  const raw = nulls(bars.length);
  for (let i = kPeriod - 1; i < bars.length; i++) {
    let hh = -Infinity;
    let ll = Infinity;
    for (let k = i - kPeriod + 1; k <= i; k++) {
      hh = Math.max(hh, bars[k]!.h);
      ll = Math.min(ll, bars[k]!.l);
    }
    raw[i] = hh === ll ? 0 : (100 * (bars[i]!.c - ll)) / (hh - ll);
  }
  const k = smaOfSeries(raw, kSmooth);
  const d = smaOfSeries(k, dPeriod);
  return { k, d };
}

export interface PivotLevels {
  pivot: number;
  r1: number;
  r2: number;
  r3: number;
  s1: number;
  s2: number;
  s3: number;
}

/** Classic floor-trader pivots from one completed period's high/low/close. */
export function classicPivots(high: number, low: number, close: number): PivotLevels {
  const p = (high + low + close) / 3;
  const range = high - low;
  return {
    pivot: p,
    r1: 2 * p - low,
    s1: 2 * p - high,
    r2: p + range,
    s2: p - range,
    r3: high + 2 * (p - low),
    s3: low - 2 * (high - p),
  };
}

/**
 * Pivot series for a candle array of one period type (e.g. daily candles): the levels at index i
 * are computed from the COMPLETED candle i-1 and apply during candle i (no look-ahead).
 * Index 0 is null.
 */
export function pivotSeries(periodBars: readonly Bar[]): (PivotLevels | null)[] {
  return periodBars.map((_, i) => {
    if (i === 0) return null;
    const p = periodBars[i - 1]!;
    return classicPivots(p.h, p.l, p.c);
  });
}
